  defaultIssueStatus: defaultIssueStatusSchema.optional(),
  allowPublicProjects: allowPublicProjectsSchema.optional(),
  requireTwoFactor: requireTwoFactorSchema.optional(),
  digestHourUtc: digestHourUtcSchema.optional(),
  enabledFlagOverrides: enabledFlagOverridesSchema.optional(),
});

